// Deduplicate by business name + city (fuzzy match)
const leads = $input.all().map(i => i.json);
const seen = new Map();
const unique = [];

function normalizeString(str) {
  return (str || '').toLowerCase()
    .replace(/[^a-z0-9]/g, '')
    .trim();
}

for (const lead of leads) {
  const key = normalizeString(lead.business_name) + '_' + normalizeString(lead.city);

  if (!seen.has(key)) {
    seen.set(key, lead);
    unique.push(lead);
  } else {
    // Merge data from duplicate (prefer non-empty values)
    const existing = seen.get(key);
    for (const [field, value] of Object.entries(lead)) {
      if (value && !existing[field]) {
        existing[field] = value;
      }
    }
  }
}

return unique.map(lead => ({ json: lead }));

// Extract best email from Hunter.io results for ALL items
const allHunterResults = $input.all();
const allLeadData = $('Filter: Must Have Website').all();

return allHunterResults.map((item, index) => {
  const hunterData = (item.json || {}).data || {};
  const leadData = allLeadData[index] ? allLeadData[index].json : {};

  const emails = hunterData.emails || [];
  const priorityRoles = ['owner', 'founder', 'ceo', 'president', 'director', 'manager'];

  let bestEmail = '';
  let ownerName = '';

  for (const role of priorityRoles) {
    const match = emails.find(e =>
      (e.position || '').toLowerCase().includes(role) ||
      (e.seniority || '').toLowerCase() === 'executive'
    );
    if (match) {
      bestEmail = match.value;
      ownerName = [match.first_name, match.last_name].filter(Boolean).join(' ');
      break;
    }
  }

  if (!bestEmail && emails.length > 0) {
    bestEmail = emails[0].value;
    ownerName = [emails[0].first_name, emails[0].last_name].filter(Boolean).join(' ');
  }

  const genericEmail = hunterData.pattern ? 'info@' + (hunterData.domain || '') : '';

  return {
    ...leadData,
    email: bestEmail || genericEmail,
    owner_name: ownerName,
    email_confidence: (emails[0] || {}).confidence || 0,
    company_type: hunterData.organization || '',
    hunter_enriched: true
  };
});

// Merge Apollo enrichment data for ALL items
const allParseResults = $input.all();

let allApolloResults = [];
try {
  allApolloResults = $('Apollo.io Enrichment').all();
} catch(e) {
  // Apollo not available - continue without enrichment
}

return allParseResults.map((item, index) => {
  const leadData = item.json;
  const apolloResponse = allApolloResults[index] ? allApolloResults[index].json : {};
  const apolloData = apolloResponse.organization || {};

  return {
