const items = $input.all();
const results = [];

for (const item of items) {
  try {
    const candidates = item.json?.candidates || [];
    if (candidates.length === 0) continue;

    let text = (candidates[0]?.content?.parts?.[0]?.text || '').trim();

    // Strip markdown code fences if present
    text = text.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();

    let businesses = [];
    try {
      businesses = JSON.parse(text);
    } catch (e) {
      // Try to extract JSON array from text
      const match = text.match(/\[\s*\{[\s\S]*\}\s*\]/);
      if (match) businesses = JSON.parse(match[0]);
    }

    if (!Array.isArray(businesses)) continue;

    const context = $('Generate Search Queries').first().json;

    for (const biz of businesses) {
      if (!biz.business_name) continue;
      results.push({
        json: {
          business_name: biz.business_name || '',
          address: biz.address || '',
          phone: biz.phone || '',
          website: biz.website || '',
          rating: biz.rating || null,
          review_count: biz.review_count || 0,
          industry: context?.industry || item.json?.industry || '',
          location: context?.location || item.json?.location || '',
          source: 'gemini_search',
          timestamp: new Date().toISOString()
        }
      });
    }
  } catch (e) {
    // Skip failed items
  }
}

return results.length > 0 ? results : [{ json: { _empty: true } }];
